//! 🧱️ Complete nested envelope, independent SQL and actual declaration-owned I/O laws.
use super::Din4108Snapshot;
#[test]
fn sqlite_snapshot_din4108_owned_native_decoder_controls_both_physical_payloads(){
 use store::io::IoPayload;
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
  let restored=Din4108Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);
  assert!(Din4108Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(Din4108Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(Din4108Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
}
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding,SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue}};

fn fixture()->Din4108Snapshot{store::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn database(snapshot:&Din4108Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn roundtrip(snapshot:&Din4108Snapshot)->Din4108Snapshot{let bytes=export_sqlite_database(&database(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();Din4108Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn set_every_word(s:&mut Din4108Snapshot,v:f64){s.t_int_c=v;s.rh_int=v;s.airtightness_n50=v;for z in &mut s.zones{z.floor_area_m2=v;for w in &mut z.windows{w.inclination_deg=v;w.area_m2=v;w.g_value=v;w.shading_fc=v;}}for e in &mut s.elements{e.orientation_deg=v;e.inclination_deg=v;e.area_m2=v;e.delta_u_g=v;e.delta_u_f=v;e.delta_u_r=v;for l in &mut e.layers{l.thickness_m=v;l.lambda=v;l.mu=v;l.density=v;for segment in &mut l.segments{segment.fraction=v;segment.lambda=v;segment.mu=v;segment.density=v;}}}for b in &mut s.thermal_bridges{b.psi=v;b.length_m=v;}}

